import { Checkbox } from '@/components/ui/checkbox';
import { FormField } from './form-field';
import type { FormFieldBaseProps } from './types';

export type CheckboxFieldProps = Omit<FormFieldBaseProps, 'orientation'>;

export function CheckboxField({
    name,
    label,
    labelAction,
    'aria-label': ariaLabel,
    description,
    className,
    disabled,
}: CheckboxFieldProps) {
    return (
        <FormField
            name={name}
            label={label}
            labelAction={labelAction}
            aria-label={ariaLabel}
            description={description}
            className={className}
            orientation="horizontal"
            disabled={disabled}
            controlFirst
        >
            {({ field, ...aria }) => (
                <Checkbox
                    {...aria}
                    name={field.name}
                    ref={field.ref}
                    checked={Boolean(field.value)}
                    disabled={field.disabled}
                    onBlur={field.onBlur}
                    onCheckedChange={(checked) => {
                        field.onChange(checked);
                    }}
                />
            )}
        </FormField>
    );
}

import { format, isValid, parse } from 'date-fns';
import { CalendarIcon } from 'lucide-react';
import { useState } from 'react';
import { Button } from '@/components/ui/button';
import { Calendar } from '@/components/ui/calendar';
import {
    Popover,
    PopoverContent,
    PopoverTrigger,
} from '@/components/ui/popover';
import { cn } from '@/lib/utils';
import { FormField } from './form-field';
import type { FormFieldBaseProps } from './types';

/**
 * The value stored in form state is a `yyyy-MM-dd` string, never a Date.
 * A Date would be serialised in the browser's timezone and can arrive at
 * Laravel as the previous day.
 */
const VALUE_FORMAT = 'yyyy-MM-dd';

function toDate(value: unknown): Date | undefined {
    if (typeof value !== 'string' || value === '') {
        return undefined;
    }

    const parsed = parse(value, VALUE_FORMAT, new Date());

    return isValid(parsed) ? parsed : undefined;
}

export type DateFieldProps = FormFieldBaseProps & {
    placeholder?: string;
    /** How the chosen day is shown on the trigger. The stored value stays `yyyy-MM-dd`. */
    displayFormat?: string;
    triggerClassName?: string;
};

export function DateField({
    name,
    label,
    labelAction,
    'aria-label': ariaLabel,
    description,
    className,
    orientation,
    disabled,
    placeholder = 'Pick a date',
    displayFormat = 'PPP',
    triggerClassName,
}: DateFieldProps) {
    const [open, setOpen] = useState(false);

    return (
        <FormField
            name={name}
            label={label}
            labelAction={labelAction}
            aria-label={ariaLabel}
            description={description}
            className={className}
            orientation={orientation}
            disabled={disabled}
        >
            {({ field, ...aria }) => {
                const selected = toDate(field.value);

                return (
                    <Popover open={open} onOpenChange={setOpen}>
                        <PopoverTrigger
                            render={
                                <Button
                                    {...aria}
                                    ref={field.ref}
                                    type="button"
                                    variant="outline"
                                    disabled={field.disabled}
                                    onBlur={field.onBlur}
                                    className={cn(
                                        'w-full justify-start font-normal',
                                        !selected && 'text-muted-foreground',
                                        triggerClassName,
                                    )}
                                >
                                    <CalendarIcon />
                                    {selected
                                        ? format(selected, displayFormat)
                                        : placeholder}
                                </Button>
                            }
                        />

                        <PopoverContent className="w-auto p-0" align="start">
                            <Calendar
                                mode="single"
                                autoFocus
                                selected={selected}
                                defaultMonth={selected}
                                onSelect={(date) => {
                                    field.onChange(
                                        date ? format(date, VALUE_FORMAT) : '',
                                    );
                                    setOpen(false);
                                }}
                            />
                        </PopoverContent>
                    </Popover>
                );
            }}
        </FormField>
    );
}

function isPlainObject(value: unknown): value is Record<string, unknown> {
    return (
        typeof value === 'object' &&
        value !== null &&
        !Array.isArray(value) &&
        Object.getPrototypeOf(value) === Object.prototype
    );
}

/**
 * Flattens the form's default values into the set of paths a field may bind to.
 * Arrays contribute only their own key, since their indices are not known upfront.
 */
export function collectFieldPaths(
    values: unknown,
    prefix = '',
    paths = new Set<string>(),
): Set<string> {
    if (!isPlainObject(values)) {
        return paths;
    }

    for (const [key, value] of Object.entries(values)) {
        const path = prefix ? `${prefix}.${key}` : key;

        paths.add(path);
        collectFieldPaths(value, path, paths);
    }

    return paths;
}

/** Paths that walk into an array are accepted whenever their root key exists. */
export function isKnownFieldPath(paths: Set<string>, name: string): boolean {
    if (paths.has(name)) {
        return true;
    }

    if (/\.\d+(\.|$)/.test(name)) {
        return paths.has(name.split('.')[0]);
    }

    return false;
}

import { createContext } from 'react';

/**
 * Paths the surrounding form knows about, derived from its default values.
 * `null` when no form provides it, which switches the dev-time name check off.
 */
export const FieldPathsContext = createContext<Set<string> | null>(null);

import type { ReactNode } from 'react';
import { useContext, useEffect, useId } from 'react';
import { Controller, useFormContext } from 'react-hook-form';
import {
    Field,
    FieldDescription,
    FieldError,
    FieldLabel,
} from '@/components/ui/field';
import { cn } from '@/lib/utils';
import { isKnownFieldPath } from './field-paths';
import { FieldPathsContext } from './form-context';
import type {
    FieldOrientation,
    FormFieldBaseProps,
    FormFieldRenderArgs,
} from './types';

/**
 * Base UI's Field.Root is a plain column and has no `orientation` prop, so the
 * variants the form primitives were built against live here. Keeping them out
 * of `ui/field.tsx` means a registry resync cannot drop them again.
 */
const orientationClassName: Record<FieldOrientation, string> = {
    vertical: '',
    horizontal: 'flex-row items-center *:data-[slot=field-label]:flex-auto',
    responsive:
        'sm:flex-row sm:items-center sm:*:data-[slot=field-label]:flex-auto',
};

export type FormFieldProps = FormFieldBaseProps & {
    /**
     * Renders the control and nothing else. The label, description, error and
     * aria wiring around it belong to FormField.
     */
    children: (args: FormFieldRenderArgs) => ReactNode;
    /** Places the control before its label, as checkboxes and switches expect. */
    controlFirst?: boolean;
};

/**
 * `name` is typed as a plain string, so a typo cannot be caught by the compiler.
 * This checks it against the paths derived from the form's default values and
 * fails loudly in development instead of silently leaving the field unbound.
 */
function useKnownFieldName(name: string): void {
    const fieldPaths = useContext(FieldPathsContext);

    useEffect(() => {
        if (
            !import.meta.env.DEV ||
            fieldPaths === null ||
            isKnownFieldPath(fieldPaths, name)
        ) {
            return;
        }

        throw new Error(
            `FormField: field "${name}" is not part of the form schema. Available paths: ${[...fieldPaths].sort().join(', ')}.`,
        );
    }, [fieldPaths, name]);
}

export function FormField({
    name,
    label,
    labelAction,
    'aria-label': ariaLabel,
    description,
    className,
    orientation,
    disabled,
    controlFirst = false,
    children,
}: FormFieldProps) {
    const { control } = useFormContext();
    const generatedId = useId();

    useKnownFieldName(name);

    const id = `${name}-${generatedId}`;
    const descriptionId = `${id}-description`;
    const errorId = `${id}-error`;

    return (
        <Controller
            control={control}
            name={name}
            disabled={disabled}
            render={({ field, fieldState }) => {
                const invalid = Boolean(fieldState.error);
                const describedBy =
                    [
                        description ? descriptionId : null,
                        invalid ? errorId : null,
                    ]
                        .filter(Boolean)
                        .join(' ') || undefined;

                const controlNode = children({
                    field,
                    id,
                    'aria-invalid': invalid || undefined,
                    'aria-describedby': describedBy,
                    'aria-label': ariaLabel,
                });

                const fieldLabel = label ? (
                    <FieldLabel htmlFor={id}>{label}</FieldLabel>
                ) : null;

                // `w-full` is what lets the action sit at the far edge: Field
                // is `items-start`, so without it this row shrinks to its own
                // content and there is no free space to justify against.
                const labelNode =
                    fieldLabel && labelAction ? (
                        <div className="flex w-full items-center justify-between gap-2">
                            {fieldLabel}
                            {labelAction}
                        </div>
                    ) : (
                        fieldLabel
                    );

                return (
                    <Field
                        className={cn(
                            orientationClassName[orientation ?? 'vertical'],
                            className,
                        )}
                        invalid={invalid}
                    >
                        {controlFirst ? controlNode : labelNode}
                        {controlFirst ? labelNode : controlNode}

                        {description ? (
                            <FieldDescription id={descriptionId}>
                                {description}
                            </FieldDescription>
                        ) : null}

                        {invalid ? (
                            <FieldError id={errorId} match>
                                {fieldState.error?.message}
                            </FieldError>
                        ) : null}
                    </Field>
                );
            }}
        />
    );
}

import type { ComponentProps, ReactNode } from 'react';
import type { FieldErrors, FieldValues } from 'react-hook-form';
import { FormProvider } from 'react-hook-form';
import type { ZodType } from 'zod';
import AlertError from '@/components/common/alert-error';
import { FieldPathsContext } from './form-context';
import type {
    InertiaFormReturn,
    SchemaInput,
    SchemaOutput,
    UseInertiaFormOptions,
} from './use-inertia-form';
import { useInertiaForm } from './use-inertia-form';

type FormElementProps = Omit<
    ComponentProps<'form'>,
    'onSubmit' | 'action' | 'method' | 'children'
>;

type FormChildren<TInput extends FieldValues, TOutput> =
    | ReactNode
    | ((form: InertiaFormReturn<TInput, TOutput>) => ReactNode);

type ProvidedFormProps<
    TInput extends FieldValues,
    TOutput,
> = FormElementProps & {
    /** An existing form from `useInertiaForm`, for pages that need its methods outside the markup. */
    form: InertiaFormReturn<TInput, TOutput>;
    children: FormChildren<TInput, TOutput>;
};

type ManagedFormProps<TSchema extends ZodType<unknown, FieldValues>> =
    FormElementProps &
        UseInertiaFormOptions<TSchema> & {
            form?: undefined;
            children: FormChildren<SchemaInput<TSchema>, SchemaOutput<TSchema>>;
        };

export type FormProps<
    TSchema extends ZodType<unknown, FieldValues>,
    TInput extends FieldValues,
    TOutput,
> = ProvidedFormProps<TInput, TOutput> | ManagedFormProps<TSchema>;

/** Server errors that matched no field are stored under `root` and surfaced as one alert. */
function collectRootErrors(errors: FieldErrors): string[] {
    if (!errors.root) {
        return [];
    }

    return Object.values(
        errors.root as unknown as Record<string, { message?: unknown }>,
    )
        .map((error) =>
            typeof error?.message === 'string' ? error.message : null,
        )
        .filter((message): message is string => message !== null);
}

function FormShell<TInput extends FieldValues, TOutput>({
    form,
    children,
    ...formProps
}: ProvidedFormProps<TInput, TOutput>) {
    const { submit, fieldPaths, ...methods } = form;
    const rootErrors = collectRootErrors(methods.formState.errors);

    return (
        <FieldPathsContext.Provider value={fieldPaths}>
            <FormProvider {...methods}>
                <form {...formProps} onSubmit={submit} noValidate>
                    {rootErrors.length > 0 ? (
                        <AlertError errors={rootErrors} />
                    ) : null}

                    {typeof children === 'function' ? children(form) : children}
                </form>
            </FormProvider>
        </FieldPathsContext.Provider>
    );
}

function ManagedForm<TSchema extends ZodType<unknown, FieldValues>>({
    action,
    schema,
    defaultValues,
    resetOnSuccess,
    transform,
    onSuccess,
    onError,
    visit,
    mode,
    reValidateMode,
    ...formProps
}: ManagedFormProps<TSchema>) {
    const form = useInertiaForm<TSchema>({
        action,
        schema,
        defaultValues,
        resetOnSuccess,
        transform,
        onSuccess,
        onError,
        visit,
        mode,
        reValidateMode,
    });

    return <FormShell {...formProps} form={form} />;
}

/**
 * Renders the form element, provides the react-hook-form context and shows any
 * server error that belongs to no field. Creates the form itself unless one is
 * passed in.
 */
export function Form<
    TSchema extends ZodType<unknown, FieldValues>,
    TInput extends FieldValues = SchemaInput<TSchema>,
    TOutput = SchemaOutput<TSchema>,
>(props: FormProps<TSchema, TInput, TOutput>) {
    if (props.form) {
        return <FormShell {...props} />;
    }

    return <ManagedForm {...props} />;
}

export type { CheckboxFieldProps } from './checkbox-field';
export { CheckboxField } from './checkbox-field';
